};
</script>
<script>
(async function(){
  const resp = await fetch('file:///app/benchmark/source_data.json');
  const src = await resp.json();
  const rows = src.national_development;

  const fields = [
    ['gdp_per_capita_usd','GDP per Capita (USD)'],
    ['hdi','HDI (0-1)'],
    ['freedom_index','Freedom Index (0-100)'],
    ['corruption_perceptions_index','CPI (0-100)'],
    ['co2_emissions_per_capita_tons','CO2 per Capita (tons)'],
    ['military_expenditure_pct_gdp','Military Expenditure (% GDP)'],
    ['internet_penetration_pct','Internet Penetration (%)']
  ];

  const palette = {
    'High':'#1f77b4',
    'Upper-Middle':'#2ca02c',
    'Lower-Middle':'#ff7f0e',
    'Low':'#d62728'
  };

  const mins = {}, maxs = {};
  for (const [k] of fields) {
    mins[k] = Math.min(...rows.map(r=>r[k]));
    maxs[k] = Math.max(...rows.map(r=>r[k]));
  }
  const norm = (v,k)=> (maxs[k]===mins[k]?0.5:(v-mins[k])/(maxs[k]-mins[k]));

  const canvas = document.getElementById('c');
  const ctx = canvas.getContext('2d');
  const W = canvas.width, H = canvas.height;
  const margin = {l:130,r:180,t:140,b:170};
  const pw = W - margin.l - margin.r;
  const ph = H - margin.t - margin.b;

  ctx.fillStyle = '#fff'; ctx.fillRect(0,0,W,H);

  // Title
  ctx.fillStyle = '#111';
  ctx.font = 'bold 46px Inter, Arial, sans-serif';
  ctx.fillText('National Development Profiles Across Income Groups', 80, 70);
  ctx.font = '28px Inter, Arial, sans-serif';
  ctx.fillStyle = '#444';
  ctx.fillText('Parallel coordinates of 30 countries; thin lines = countries, bold lines = group median profile', 80, 112);

  // Grid + axes
  for (let gy=0; gy<=5; gy++) {
    const y = margin.t + ph*(gy/5);
    ctx.strokeStyle = '#e5e7eb';
    ctx.lineWidth = 1;
    ctx.setLineDash([6,6]);
    ctx.beginPath(); ctx.moveTo(margin.l,y); ctx.lineTo(margin.l+pw,y); ctx.stroke();
    ctx.setLineDash([]);
    const val = (1-gy/5).toFixed(1);
    ctx.fillStyle = '#666';
    ctx.font = '20px Inter, Arial, sans-serif';
    ctx.fillText(val, margin.l-46, y+6);
  }

  const xs = fields.map((_,i)=> margin.l + (pw*(i/(fields.length-1))));
  for (let i=0;i<fields.length;i++) {
    const x = xs[i];
    ctx.strokeStyle = '#cbd5e1';
    ctx.lineWidth = 1.5;
    ctx.beginPath(); ctx.moveTo(x, margin.t); ctx.lineTo(x, margin.t+ph); ctx.stroke();

    ctx.save();
    ctx.translate(x, H-margin.b+24);
    ctx.rotate(-Math.PI/8);
    ctx.fillStyle='#222';
    ctx.font='20px Inter, Arial, sans-serif';
    ctx.fillText(fields[i][1], 0, 0);
    ctx.restore();
  }

  // Country lines
  for (const r of rows) {
    ctx.strokeStyle = palette[r.income_group] || '#888';
    ctx.globalAlpha = 0.35;
    ctx.lineWidth = 2;
    ctx.beginPath();
    fields.forEach(([k],i)=>{
      const y = margin.t + (1-norm(r[k],k))*ph;
      const x = xs[i];
      if (i===0) ctx.moveTo(x,y); else ctx.lineTo(x,y);
    });
    ctx.stroke();
  }
  ctx.globalAlpha = 1;

  // Median lines per group
  const groups = {};
  for (const r of rows) (groups[r.income_group] ||= []).push(r);
  for (const g of Object.keys(groups)) {
    ctx.strokeStyle = palette[g];
    ctx.lineWidth = 6;
    ctx.beginPath();
    fields.forEach(([k],i)=>{
      const vals = groups[g].map(r=>r[k]).sort((a,b)=>a-b);
      const n = vals.length;
      const med = n%2? vals[(n-1)/2] : (vals[n/2-1]+vals[n/2])/2;
      const y = margin.t + (1-norm(med,k))*ph;
      const x = xs[i];
      if (i===0) ctx.moveTo(x,y); else ctx.lineTo(x,y);
    });
    ctx.stroke();
  }

  // Axis labels
  ctx.fillStyle = '#111';
  ctx.font = 'bold 24px Inter, Arial, sans-serif';
  ctx.fillText('Normalized Value (0-1, min-max scaled within each indicator)', 80, H-36);
  ctx.save();
  ctx.translate(36, margin.t + ph/2);
  ctx.rotate(-Math.PI/2);
  ctx.fillText('Normalized Value (0-1)', 0, 0);
  ctx.restore();

  // Legend
  const legendX = W-330, legendY = 180;
  ctx.fillStyle='#111'; ctx.font='bold 24px Inter, Arial, sans-serif';
  ctx.fillText('Income Group', legendX, legendY);
  let i=0;
  for (const g of ['High','Upper-Middle','Lower-Middle','Low']) {
    if (!groups[g]) continue;
    const y = legendY + 40 + i*42;
    ctx.strokeStyle = palette[g]; ctx.lineWidth=8;
    ctx.beginPath(); ctx.moveTo(legendX, y); ctx.lineTo(legendX+46, y); ctx.stroke();
    ctx.fillStyle='#222'; ctx.font='22px Inter, Arial, sans-serif';
    ctx.fillText(g, legendX+60, y+8);
    i++;
  }

  // Source note
  ctx.fillStyle = '#666';
  ctx.font = '18px Inter, Arial, sans-serif';
  ctx.fillText('Source: /app/benchmark/source_data.json (national_development, approx. 2023 estimates)', 80, H-10);

  window.__done = true;
})();
</script>
</body>
</html>
